def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most frequent nonzero color is the background; the other nonzero
    # color marks the pattern to search for.
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker = next(color for color in counts if color != background)

    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == marker]
    min_r = min(r for r, c in points)
    max_r = max(r for r, c in points)
    min_c = min(c for r, c in points)
    max_c = max(c for r, c in points)
    pattern = [(r - min_r, c - min_c) for r, c in points]

    out = [row[:] for row in grid]
    ph, pw = max_r - min_r + 1, max_c - min_c + 1

    for r in range(h - ph + 1):
        for c in range(w - pw + 1):
            if all(grid[r + dr][c + dc] == 0 for dr, dc in pattern):
                for dr, dc in pattern:
                    out[r + dr][c + dc] = marker

    return out
